+    fn start_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Vec<UiAction> {
+        let pane = if self.focus == PaneFocus::Left && !self.left_visible {
+            PaneFocus::Right
+        } else {
+            self.focus
+        };
+        let position = self.visual_start_position(pane, right_content, right_cursor_column);
+        self.focus = pane;
+        self.mode = UiMode::Visual;
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+        Vec::new()
+    }
+
+    fn switch_visual_selection_kind(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.kind = kind;
+        } else {
+            let _ = self.start_visual_selection(kind, right_content, right_cursor_column);
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(selection) = self.visual_selection.clone() else {
+            return;
+        };
+        let lines = self.selectable_lines(selection.pane, right_content);
+        if lines.is_empty() {
+            return;
+        }
+
+        let row = add_signed(selection.cursor.row, row_delta).min(lines.len() - 1);
+        let line_width = line_width(&lines[row]);
+        let max_column = line_width.saturating_sub(1);
+        let column = add_signed(selection.cursor.column, column_delta).min(max_column);
+
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = TextPosition { row, column };
+        }
+    }
+
+    fn copy_visual_selection(
+        &mut self,
+        right_content: &str,
+        forced_kind: Option<VisualSelectionKind>,
+    ) -> Vec<UiAction> {
+        let Some(selection) = self.visual_selection.clone() else {
+            return Vec::new();
+        };
+        let lines = self.selectable_lines(selection.pane, right_content);
+        let kind = forced_kind.unwrap_or(selection.kind);
+        let copied = selected_text(&lines, &selection, kind);
+        self.cancel_visual_selection();
+        self.show_status_notice(
+            COPY_SELECTION_NOTICE,
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+        vec![UiAction::CopySelection(copied)]
+    }
+
+    fn copy_current_line(
+        &mut self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Vec<UiAction> {
+        let pane = if self.focus == PaneFocus::Left && !self.left_visible {
+            PaneFocus::Right
+        } else {
+            self.focus
+        };
+        let lines = self.selectable_lines(pane, right_content);
+        if lines.is_empty() {
+            return Vec::new();
+        }
+        let position = self.visual_start_position(pane, right_content, right_cursor_column);
+        self.show_status_notice(
+            COPY_SELECTION_NOTICE,
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+        vec![UiAction::CopySelection(lines[position.row].clone())]
+    }
+
+    fn visual_start_position(
+        &self,
+        pane: PaneFocus,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPosition {
+        let lines = self.selectable_lines(pane, right_content);
+        if lines.is_empty() {
+            return TextPosition { row: 0, column: 0 };
+        }
+        let row = match pane {
+            PaneFocus::Left => self.left_control_row_index().min(lines.len() - 1),
+            PaneFocus::Right => lines.len() - 1,
+        };
+        let line_width = line_width(&lines[row]);
+        let max_column = line_width.saturating_sub(1);
+        let column = match pane {
+            PaneFocus::Left => 0,
+            PaneFocus::Right => right_cursor_column.unwrap_or(0).min(max_column),
+        };
+        TextPosition { row, column }
+    }
+
+    fn selectable_lines(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self
+                .left_pane_rows()
+                .into_iter()
+                .map(|row| row.text)
+                .collect(),
+            PaneFocus::Right => self
+                .visible_right_content(right_content)
+                .lines()
+                .map(ToString::to_string)
+                .collect(),
+        }
+    }
+
+    fn selection_range_for_line(
+        &self,
+        pane: PaneFocus,
+        row_index: usize,
+        line: &str,
+    ) -> Option<(usize, usize)> {
+        let selection = self.visual_selection.as_ref()?;
+        if selection.pane != pane {
+            return None;
+        }
+        selection_range(selection, selection.kind, row_index, line_width(line))
+    }
+
+    fn left_control_row_index(&self) -> usize {
+        if self.control_selected == 0 {
+            return 0;
+        }
+
+        let mut current_row = 1;
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            if self.control_selected == visible_position + 1 {
+                return current_row;
+            }
+
+            current_row += 1;
+            let agent = &self.agents[*agent_index];
+            if !agent.modified_files.is_empty() {
+                current_row += 1;
+            }
+            for linked_agents in [
+                &agent.conflicting_agents,
+                &agent.depends_on,
+                &agent.depended_on_by,
+            ] {
+                if !linked_agents.is_empty() {
+                    current_row += 1;
+                }
+            }
+        }
+
+        current_row.saturating_sub(1)
+    }
