 fn cursor_char_count(text: &str, cursor: usize) -> usize {
     text.char_indices()
         .take_while(|(index, _)| *index < cursor)
         .count()
 }
+
+fn add_signed(value: usize, delta: isize) -> usize {
+    if delta.is_negative() {
+        value.saturating_sub(delta.unsigned_abs())
+    } else {
+        value.saturating_add(delta as usize)
+    }
+}
+
+fn line_width(line: &str) -> usize {
+    line.chars().count()
+}
+
+fn selected_text(
+    lines: &[String],
+    selection: &VisualSelection,
+    kind: VisualSelectionKind,
+) -> String {
+    if lines.is_empty() {
+        return String::new();
+    }
+
+    lines
+        .iter()
+        .enumerate()
+        .filter_map(|(row_index, line)| {
+            let (start, end) = selection_range(selection, kind, row_index, line_width(line))?;
+            Some(line.chars().skip(start).take(end - start).collect::<String>())
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_range(
+    selection: &VisualSelection,
+    kind: VisualSelectionKind,
+    row_index: usize,
+    line_width: usize,
+) -> Option<(usize, usize)> {
+    match kind {
+        VisualSelectionKind::Character => character_selection_range(selection, row_index, line_width),
+        VisualSelectionKind::Line => line_selection_range(selection, row_index, line_width),
+        VisualSelectionKind::Block => block_selection_range(selection, row_index, line_width),
+    }
+}
+
+fn character_selection_range(
+    selection: &VisualSelection,
+    row_index: usize,
+    line_width: usize,
+) -> Option<(usize, usize)> {
+    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+    if row_index < start.row || row_index > end.row {
+        return None;
+    }
+
+    if start.row == end.row {
+        return bounded_range(start.column, end.column.saturating_add(1), line_width);
+    }
+
+    if row_index == start.row {
+        bounded_range(start.column, line_width, line_width)
+    } else if row_index == end.row {
+        bounded_range(0, end.column.saturating_add(1), line_width)
+    } else {
+        bounded_range(0, line_width, line_width)
+    }
+}
+
+fn line_selection_range(
+    selection: &VisualSelection,
+    row_index: usize,
+    line_width: usize,
+) -> Option<(usize, usize)> {
+    let start = selection.anchor.row.min(selection.cursor.row);
+    let end = selection.anchor.row.max(selection.cursor.row);
+    (start..=end)
+        .contains(&row_index)
+        .then_some((0, line_width))
+}
+
+fn block_selection_range(
+    selection: &VisualSelection,
+    row_index: usize,
+    line_width: usize,
+) -> Option<(usize, usize)> {
+    let start_row = selection.anchor.row.min(selection.cursor.row);
+    let end_row = selection.anchor.row.max(selection.cursor.row);
+    if !(start_row..=end_row).contains(&row_index) {
+        return None;
+    }
+
+    let start_column = selection.anchor.column.min(selection.cursor.column);
+    let end_column = selection
+        .anchor
+        .column
+        .max(selection.cursor.column)
+        .saturating_add(1);
+    bounded_range(start_column, end_column, line_width)
+}
+
+fn bounded_range(start: usize, end: usize, line_width: usize) -> Option<(usize, usize)> {
+    let start = start.min(line_width);
+    let end = end.min(line_width);
+    (start < end).then_some((start, end))
+}
+
+fn ordered_positions(left: TextPosition, right: TextPosition) -> (TextPosition, TextPosition) {
+    if (left.row, left.column) <= (right.row, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}

