+fn selection_range(
+    selection: &VisualSelection,
+    kind: VisualSelectionKind,
+    row_index: usize,
+    line_width: usize,
+) -> Option<(usize, usize)> {
+    match kind {
+        VisualSelectionKind::Character => {
+            character_selection_range(selection, row_index, line_width)
+        }
+        VisualSelectionKind::Line => line_selection_range(selection, row_index, line_width),
+        VisualSelectionKind::Block => block_selection_range(selection, row_index, line_width),
+    }
